<?php
/**
 * Fix autoload_static.php to use relative paths (works on both Windows and Linux)
 */
$vendorDir = __DIR__ . '/../..';
$autoloadStaticFile = __DIR__ . '/autoload_static.php';

// Build the mappings
$prefixDirsPsr4 = [
    'Symfony\\Polyfill\\Php80\\' => [__DIR__ . '/../symfony/polyfill-php80'],
    'Symfony\\Polyfill\\Mbstring\\' => [__DIR__ . '/../symfony/polyfill-mbstring'],
    'Symfony\\Polyfill\\Ctype\\' => [__DIR__ . '/../symfony/polyfill-ctype'],
    'PhpOption\\' => [__DIR__ . '/../phpoption/phpoption/src/PhpOption'],
    'GrahamCampbell\\ResultType\\' => [__DIR__ . '/../graham-campbell/result-type/src'],
    'Dotenv\\' => [__DIR__ . '/../vlucas/phpdotenv/src'],
    'App\\' => [dirname(__DIR__) . '/app'],
];

$prefixLengthsPsr4 = [];
foreach ($prefixDirsPsr4 as $prefix => $dirs) {
    $firstChar = $prefix[0];
    $prefixLengthsPsr4[$firstChar][$prefix] = strlen($prefix);
}

$files = [
    __DIR__ . '/../symfony/polyfill-php80/bootstrap.php',
    __DIR__ . '/../symfony/polyfill-mbstring/bootstrap.php',
    __DIR__ . '/../symfony/polyfill-ctype/bootstrap.php',
];

$classMap = [];

// Generate the PHP code
$code = "<?php\n\n";
$code .= "// autoload_static.php @generated by Composer (fixed for cross-platform)\n\n";
$code .= "namespace Composer\Autoload;\n\n";
$code .= "class ComposerStaticInitc50ea07b37cdd16c9c4f7e32467755b1\n";
$code .= "{\n";

// Files
$code .= "    public static \$files = array (\n";
foreach ($files as $f) {
    $ident = md5($f);
    $code .= "        '{$ident}' => '" . str_replace('\\', '/', $f) . "',\n";
}
$code .= "    );\n\n";

// Prefix lengths
$code .= "    public static \$prefixLengthsPsr4 = array (\n";
foreach ($prefixLengthsPsr4 as $char => $prefixes) {
    $code .= "        '{$char}' => \n";
    $code .= "        array (\n";
    foreach ($prefixes as $prefix => $len) {
        $code .= "            '{$prefix}' => {$len},\n";
    }
    $code .= "        ),\n";
}
$code .= "    );\n\n";

// Prefix dirs
$code .= "    public static \$prefixDirsPsr4 = array (\n";
foreach ($prefixDirsPsr4 as $prefix => $dirs) {
    $code .= "        '{$prefix}' => \n";
    $code .= "        array (\n";
    foreach ($dirs as $d) {
        $code .= "            0 => '{$d}',\n";
    }
    $code .= "        ),\n";
}
$code .= "    );\n\n";

// Class map
$code .= "    public static \$classMap = array (\n";
foreach ($classMap as $cls => $path) {
    $code .= "        '{$cls}' => '{$path}',\n";
}
$code .= "        'Composer\\\\InstalledVersions' => __DIR__ . '/InstalledVersions.php',\n";
$code .= "    );\n\n";

// getInitializer
$code .= "    public static function loadFiles(\$fileIdentifier, \$file)\n";
$code .= "    {\n";
$code .= "        if (empty(\$GLOBALS['__composer_autoload_files'][\$fileIdentifier])) {\n";
$code .= "            \$GLOBALS['__composer_autoload_files'][\$fileIdentifier] = true;\n";
$code .= "            require \$file;\n";
$code .= "        }\n";
$code .= "    }\n\n";

$code .= "    public static function getInitializer(ClassLoader \$loader)\n";
$code .= "    {\n";
$code .= "        return \\Closure::bind(function () use (\$loader) {\n";
$code .= "            \$loader->prefixLengthsPsr4 = ComposerStaticInitc50ea07b37cdd16c9c4f7e32467755b1::\$prefixLengthsPsr4;\n";
$code .= "            \$loader->prefixDirsPsr4 = ComposerStaticInitc50ea07b37cdd16c9c4f7e32467755b1::\$prefixDirsPsr4;\n";
$code .= "            \$loader->classMap = ComposerStaticInitc50ea07b37cdd16c9c4f7e32467755b1::\$classMap;\n\n";
$code .= "        }, null, ClassLoader::class);\n";
$code .= "    }\n";
$code .= "}\n";

file_put_contents($autoloadStaticFile, $code);
echo "Written {$autoloadStaticFile}\n";

// Also fix autoload_real.php to include files
$realFile = __DIR__ . '/autoload_real.php';
$realContent = file_get_contents($realFile);
$hash = 'c50ea07b37cdd16c9c4f7e32467755b1';

// Remove any existing file loader code
$realContent = preg_replace('/\\\$includeFiles.*?foreach.*?loadFiles.*?}/s', '', $realContent);

// Add files loading after register
$fileCode = <<<PHP

        \$includeFiles = \\Composer\\Autoload\\ComposerStaticInit{$hash}::\$files;
        foreach (\$includeFiles as \$fileIdentifier => \$file) {
            \\Composer\\Autoload\\ComposerStaticInit{$hash}::loadFiles(\$fileIdentifier, \$file);
        }

PHP;

$realContent = str_replace(
    "\$loader->register(true);\n\n        return \$loader;",
    "\$loader->register(true);\n        {$fileCode}\n        return \$loader;",
    $realContent
);

file_put_contents($realFile, $realContent);
echo "Updated autoload_real.php\n";

echo "\nVerification...\n";
require $autoloadStaticFile;
$tests = ['Dotenv\\Dotenv', 'PhpOption\\Option', 'App\\Utils\\Config'];
foreach ($tests as $class) {
    echo "  {$class}: " . (class_exists($class) ? 'OK' : 'MISSING') . "\n";
}
